package com.locallaunch.controller;
import com.locallaunch.entity.Product; import com.locallaunch.service.ProductService; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/products") public class ProductController { private final ProductService service; public ProductController(ProductService s){service=s;} @PostMapping public Product create(@Valid @RequestBody Product p){return service.saveProduct(p);} @GetMapping("/business/{businessId}") public List<Product> mine(@PathVariable Long businessId){return service.getMyProductsByBusinessId(businessId);} @PutMapping("/{id}") public Product update(@PathVariable Long id,@Valid @RequestBody Product p){return service.updateProduct(id,p);} @DeleteMapping("/{id}") public ResponseEntity<String> delete(@PathVariable Long id){service.deleteProduct(id);return ResponseEntity.ok("Product deleted successfully");} }
